-- Ссылки в SEO-блоке главной (module 36): язык-зависимые адреса и актуальные страницы
UPDATE `oc_module` SET `setting`='{"name":"CodeCart PRO \\u2014 SEO \\u0431\\u043b\\u043e\\u043a \\u0433\\u043e\\u043b\\u043e\\u0432\\u043d\\u043e\\u0457","module_description":{"1":{"title":"\\u041c\\u043e\\u0434\\u0443\\u043b\\u0456 OpenCart \\u0442\\u0430 ocStore \\u0432\\u0456\\u0434 CodeCart PRO","description":"&lt;div class=&quot;ccp-home-seo&quot;&gt;&lt;h2&gt;\\u041c\\u043e\\u0434\\u0443\\u043b\\u0456 \\u0434\\u043b\\u044f OpenCart \\u0442\\u0430 ocStore&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;CodeCart PRO&lt;/strong&gt; \\u0440\\u043e\\u0437\\u0440\\u043e\\u0431\\u043b\\u044f\\u0454 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0448\\u0438\\u0440\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f OpenCart \\u0442\\u0430 ocStore 3.0.x: SEO, AI, \\u0456\\u043c\\u043f\\u043e\\u0440\\u0442 \\u0456 \\u0435\\u043a\\u0441\\u043f\\u043e\\u0440\\u0442, \\u0437\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430, \\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430, \\u043e\\u043f\\u043b\\u0430\\u0442\\u0430, \\u043a\\u0430\\u0442\\u0430\\u043b\\u043e\\u0433 \\u0442\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0437\\u0430\\u0446\\u0456\\u044f.&lt;/p&gt;&lt;p&gt;\\u0423 \\u043a\\u0430\\u0442\\u0430\\u043b\\u043e\\u0437\\u0456 \\u0454 \\u044f\\u043a \\u043a\\u043e\\u043c\\u0435\\u0440\\u0446\\u0456\\u0439\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0443\\u043b\\u0456, \\u0442\\u0430\\u043a \\u0456 \\u0431\\u0435\\u0437\\u043a\\u043e\\u0448\\u0442\\u043e\\u0432\\u043d\\u0456 \\u0440\\u0456\\u0448\\u0435\\u043d\\u043d\\u044f. &lt;strong&gt;CodeCart PRO 3.0.6&lt;/strong&gt; \\u043f\\u043e\\u0448\\u0438\\u0440\\u044e\\u0454\\u0442\\u044c\\u0441\\u044f \\u0431\\u0435\\u0437\\u043a\\u043e\\u0448\\u0442\\u043e\\u0432\\u043d\\u043e \\u0437\\u0430 GNU GPL v3. \\u041f\\u0435\\u0440\\u0435\\u0434 \\u0432\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\\u043c \\u0431\\u0443\\u0434\\u044c-\\u044f\\u043a\\u043e\\u0433\\u043e \\u0440\\u043e\\u0437\\u0448\\u0438\\u0440\\u0435\\u043d\\u043d\\u044f \\u043f\\u0435\\u0440\\u0435\\u0432\\u0456\\u0440\\u044f\\u0439\\u0442\\u0435 \\u0441\\u0443\\u043c\\u0456\\u0441\\u043d\\u0456\\u0441\\u0442\\u044c \\u0456 \\u0440\\u043e\\u0431\\u0456\\u0442\\u044c \\u043f\\u043e\\u0432\\u043d\\u0443 \\u0440\\u0435\\u0437\\u0435\\u0440\\u0432\\u043d\\u0443 \\u043a\\u043e\\u043f\\u0456\\u044e \\u0444\\u0430\\u0439\\u043b\\u0456\\u0432 \\u0442\\u0430 \\u0431\\u0430\\u0437\\u0438 \\u0434\\u0430\\u043d\\u0438\\u0445.&lt;/p&gt;&lt;p&gt;&lt;a href=&quot;/download/&quot;&gt;\\u0417\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0438\\u0442\\u0438 CodeCart PRO 3.0.6&lt;/a&gt; \\u00b7 &lt;a href=&quot;/buy-modules/&quot;&gt;\\u042f\\u043a \\u043f\\u0440\\u0438\\u0434\\u0431\\u0430\\u0442\\u0438 \\u043c\\u043e\\u0434\\u0443\\u043b\\u0456&lt;/a&gt; \\u00b7 &lt;a href=&quot;/module-prices-codecart-pro/&quot;&gt;\\u0426\\u0456\\u043d\\u0438 \\u043d\\u0430 \\u043c\\u043e\\u0434\\u0443\\u043b\\u0456&lt;/a&gt; \\u00b7 &lt;a href=&quot;/blog/&quot;&gt;\\u0421\\u0442\\u0430\\u0442\\u0442\\u0456 \\u0442\\u0430 \\u0440\\u0435\\u043a\\u043e\\u043c\\u0435\\u043d\\u0434\\u0430\\u0446\\u0456\\u0457&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;"},"2":{"title":"OpenCart and ocStore modules by CodeCart PRO","description":"&lt;div class=&quot;ccp-home-seo&quot;&gt;&lt;h2&gt;Modules for OpenCart and ocStore&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;CodeCart PRO&lt;/strong&gt; develops practical extensions for OpenCart and ocStore 3.0.x: SEO, AI, import/export, images, security, shipping, payments, catalog management and automation.&lt;/p&gt;&lt;p&gt;The catalog includes both commercial and free solutions. &lt;strong&gt;CodeCart PRO 3.0.6&lt;/strong&gt; is distributed free under GNU GPL v3. Before installing any extension, verify compatibility and create a full backup of site files and the database.&lt;/p&gt;&lt;p&gt;&lt;a href=&quot;/download-en/&quot;&gt;Download CodeCart PRO 3.0.6&lt;/a&gt; \\u00b7 &lt;a href=&quot;/buy-modules-en/&quot;&gt;How to buy modules&lt;/a&gt; \\u00b7 &lt;a href=&quot;/module-prices-codecart-pro-en/&quot;&gt;Module prices&lt;/a&gt; \\u00b7 &lt;a href=&quot;/blog/&quot;&gt;Articles and guides&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;"},"3":{"title":"\\u041c\\u043e\\u0434\\u0443\\u043b\\u0438 OpenCart \\u0438 ocStore \\u043e\\u0442 CodeCart PRO","description":"&lt;div class=&quot;ccp-home-seo&quot;&gt;&lt;h2&gt;\\u041c\\u043e\\u0434\\u0443\\u043b\\u0438 \\u0434\\u043b\\u044f OpenCart \\u0438 ocStore&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;CodeCart PRO&lt;/strong&gt; \\u0440\\u0430\\u0437\\u0440\\u0430\\u0431\\u0430\\u0442\\u044b\\u0432\\u0430\\u0435\\u0442 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u0440\\u0430\\u0441\\u0448\\u0438\\u0440\\u0435\\u043d\\u0438\\u044f \\u0434\\u043b\\u044f OpenCart \\u0438 ocStore 3.0.x: SEO, AI, \\u0438\\u043c\\u043f\\u043e\\u0440\\u0442 \\u0438 \\u044d\\u043a\\u0441\\u043f\\u043e\\u0440\\u0442, \\u0438\\u0437\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u0438\\u044f, \\u0431\\u0435\\u0437\\u043e\\u043f\\u0430\\u0441\\u043d\\u043e\\u0441\\u0442\\u044c, \\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430, \\u043e\\u043f\\u043b\\u0430\\u0442\\u0430, \\u043a\\u0430\\u0442\\u0430\\u043b\\u043e\\u0433 \\u0438 \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f.&lt;/p&gt;&lt;p&gt;\\u0412 \\u043a\\u0430\\u0442\\u0430\\u043b\\u043e\\u0433\\u0435 \\u0435\\u0441\\u0442\\u044c \\u043a\\u043e\\u043c\\u043c\\u0435\\u0440\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u0438 \\u0431\\u0435\\u0441\\u043f\\u043b\\u0430\\u0442\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u044f. &lt;strong&gt;CodeCart PRO 3.0.6&lt;/strong&gt; \\u0440\\u0430\\u0441\\u043f\\u0440\\u043e\\u0441\\u0442\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u0431\\u0435\\u0441\\u043f\\u043b\\u0430\\u0442\\u043d\\u043e \\u043f\\u043e GNU GPL v3. \\u041f\\u0435\\u0440\\u0435\\u0434 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u043e\\u0439 \\u043b\\u044e\\u0431\\u043e\\u0433\\u043e \\u0440\\u0430\\u0441\\u0448\\u0438\\u0440\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0439\\u0442\\u0435 \\u0441\\u043e\\u0432\\u043c\\u0435\\u0441\\u0442\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u0438 \\u0434\\u0435\\u043b\\u0430\\u0439\\u0442\\u0435 \\u043f\\u043e\\u043b\\u043d\\u0443\\u044e \\u0440\\u0435\\u0437\\u0435\\u0440\\u0432\\u043d\\u0443\\u044e \\u043a\\u043e\\u043f\\u0438\\u044e \\u0444\\u0430\\u0439\\u043b\\u043e\\u0432 \\u0441\\u0430\\u0439\\u0442\\u0430 \\u0438 \\u0431\\u0430\\u0437\\u044b \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445.&lt;/p&gt;&lt;p&gt;&lt;a href=&quot;/skachat/&quot;&gt;\\u0421\\u043a\\u0430\\u0447\\u0430\\u0442\\u044c CodeCart PRO 3.0.6&lt;/a&gt; \\u00b7 &lt;a href=&quot;/pokupka-moduley/&quot;&gt;\\u041a\\u0430\\u043a \\u043a\\u0443\\u043f\\u0438\\u0442\\u044c \\u043c\\u043e\\u0434\\u0443\\u043b\\u0438&lt;/a&gt; \\u00b7 &lt;a href=&quot;/module-prices-codecart-pro-ru/&quot;&gt;\\u0426\\u0435\\u043d\\u044b \\u043d\\u0430 \\u043c\\u043e\\u0434\\u0443\\u043b\\u0438&lt;/a&gt; \\u00b7 &lt;a href=&quot;/blog/&quot;&gt;\\u0421\\u0442\\u0430\\u0442\\u044c\\u0438 \\u0438 \\u0440\\u0435\\u043a\\u043e\\u043c\\u0435\\u043d\\u0434\\u0430\\u0446\\u0438\\u0438&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;"}},"status":"1"}' WHERE `module_id`=36;
-- То же в странице «Покупка модулей» (information_id=13)
UPDATE `oc_information_description` SET `description`=REPLACE(`description`,'/module-prices-codecart-pro/','/module-prices-codecart-pro-ru/') WHERE `information_id`=13 AND `language_id`=3;
UPDATE `oc_information_description` SET `description`=REPLACE(`description`,'/module-prices-codecart-pro/','/module-prices-codecart-pro-en/') WHERE `information_id`=13 AND `language_id`=2;
-- Слой CSS «Modern» (тот же код лежит в css/codecart-modern.css)
UPDATE `oc_setting` SET `value`='/* ==========================================================================
   CodeCart PRO — слой «Modern» для темы CodeCart PRO Theme 8.7.5
   Вставьте в: Система → Дизайн → Темы → CodeCart PRO → Свой код → «CSS: общий стиль сайта»
   (и включите «Кастомный CSS»). Не содержит символов «больше» и двойных кавычек —
   безопасно для сохранения через админку. Тёмная тема поддерживается.
   ========================================================================== */

/* ---- 0. Токены ---- */
body.ccp-theme{--cc-navy:#071a33;--cc-blue:#0057b7;--cc-blue-2:#1769e0;--cc-yellow:#ffd700;--cc-line:#dfe8f4;--cc-soft:#f3f7fd;--cc-card:#ffffff;--cc-text:#13294a;--cc-muted:#5b6f8a;--cc-shadow:0 14px 34px rgba(8,30,66,.10);--cc-shadow-hover:0 20px 44px rgba(8,30,66,.16)}
html.ccp-dark-theme body.ccp-theme{--cc-line:#334155;--cc-soft:#111c33;--cc-card:#1e293b;--cc-text:#f1f5fb;--cc-muted:#b8c6da;--cc-shadow:0 14px 34px rgba(0,0,0,.35);--cc-shadow-hover:0 20px 44px rgba(0,0,0,.5)}

/* ---- 1. Главная: заголовки секций ---- */
body.ccp-theme .ccp-section-head h2{font-size:clamp(22px,2.4vw,30px);font-weight:850;letter-spacing:-.02em;position:relative;padding-left:16px}
body.ccp-theme .ccp-section-head h2:before{content:\'\';position:absolute;left:0;top:.18em;bottom:.18em;width:5px;border-radius:5px;background:linear-gradient(180deg,var(--cc-blue-2),var(--cc-yellow))}
body.ccp-theme .ccp-home-section{margin:34px 0}

/* ---- 2. Плитки категорий: обложки без текста, название накладывает сама тема на языке посетителя ---- */
body.ccp-theme .ccp-category-wall{gap:18px}
body.ccp-theme .ccp-category-tile{transition:transform .2s ease,box-shadow .2s ease}
body.ccp-theme .ccp-category-tile:hover{transform:translateY(-4px);box-shadow:var(--cc-shadow-hover)}

/* ---- 3. Карточки модулей (обложки 1:1) ---- */
body.ccp-theme .ccp-product-card{border-color:var(--cc-line);box-shadow:var(--cc-shadow);transition:transform .2s ease,box-shadow .2s ease,border-color .2s ease}
body.ccp-theme .ccp-product-card:hover{transform:translateY(-4px);box-shadow:var(--cc-shadow-hover);border-color:var(--cc-blue-2)}
body.ccp-theme .ccp-product-card__name a{font-weight:800}
body.ccp-theme .ccp-product-card__name a:hover{color:var(--cc-blue-2);text-decoration:none}
body.ccp-theme .ccp-card-cart,body.ccp-theme #button-cart{background:var(--cc-yellow);border-color:var(--cc-yellow);color:var(--cc-navy);font-weight:800}
body.ccp-theme .ccp-card-cart:hover,body.ccp-theme #button-cart:hover{background:#ffe34d;border-color:#ffe34d;color:var(--cc-navy)}

/* ---- 4. Блок преимуществ ---- */
body.ccp-theme .ccp-benefit{background:var(--cc-card);border:1px solid var(--cc-line);box-shadow:var(--cc-shadow);color:var(--cc-text)}
body.ccp-theme .ccp-benefit-icon{background:linear-gradient(145deg,var(--cc-blue-2),#0a3f86);color:#fff;width:36px;height:36px}

/* ---- 5. SEO-блок главной ---- */
body.ccp-theme .ccp-home-seo{background:var(--cc-card);border:1px solid var(--cc-line);border-radius:20px;padding:clamp(20px,3vw,34px);box-shadow:var(--cc-shadow);color:var(--cc-text);line-height:1.7}
body.ccp-theme .ccp-home-seo h2{font-size:clamp(22px,2.4vw,28px);font-weight:850;margin:0 0 12px;color:var(--cc-text)}
body.ccp-theme .ccp-home-seo p{color:var(--cc-muted);margin:0 0 10px}
body.ccp-theme .ccp-home-seo a{font-weight:700;color:var(--cc-blue-2)}

/* ---- 6. Описание модуля (структура .ccp-pd из sql/04) ---- */
.ccp-pd{color:var(--cc-text,#13294a);line-height:1.7;font-size:16px}
.ccp-pd p{margin:0 0 14px}
.ccp-pd .ccp-pd__lead{font-size:18px;font-weight:600;line-height:1.6}
.ccp-pd__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:22px 0}
.ccp-pd__card{background:var(--cc-soft,#f3f7fd);border:1px solid var(--cc-line,#dfe8f4);border-radius:16px;padding:20px 22px}
.ccp-pd__card--wide{grid-column:1 / -1}
.ccp-pd__card h3{margin:0 0 12px;font-size:17px;font-weight:850;color:var(--cc-text,#13294a)}
.ccp-pd__card p{margin:0;color:var(--cc-muted,#5b6f8a)}
.ccp-pd__list{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.ccp-pd__list li{position:relative;padding-left:30px}
.ccp-pd__list li:before{content:\'\';position:absolute;left:0;top:.35em;width:18px;height:18px;border-radius:50%;background:var(--cc-blue-2,#1769e0) url(data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A//www.w3.org/2000/svg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27white%27%20stroke-width%3D%273.2%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27M5%2012.5l4.5%204.5L19%207%27/%3E%3C/svg%3E) center/12px no-repeat}
.ccp-pd__chips{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.ccp-pd__chips li{padding:6px 14px;border-radius:99px;background:var(--cc-card,#fff);border:1px solid var(--cc-line,#dfe8f4);font-weight:700;font-size:14px;color:var(--cc-text,#13294a)}
.ccp-pd__note{margin:0 0 22px;padding:14px 18px;border-radius:14px;background:#fff8dc;border:1px solid #f0dd85;color:#5c4a00;font-size:14.5px}
html.ccp-dark-theme .ccp-pd__note{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}
.ccp-pd__demo{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:24px 28px;border-radius:20px;color:#fff;background:radial-gradient(circle at 90% 0,rgba(255,215,0,.22),transparent 45%),linear-gradient(135deg,#06152b,#0b3f86)}
.ccp-pd__demo h3{margin:0 0 6px;color:#fff;font-size:20px;font-weight:850}
.ccp-pd__demo p{margin:0 0 8px;color:#cfe0f6}
.ccp-pd__creds{display:flex;gap:10px;flex-wrap:wrap}
.ccp-pd__creds span{padding:6px 14px;border-radius:10px;background:rgba(255,255,255,.12);font-size:14px;color:#fff}
.ccp-pd__creds b{color:#ffd700}
.ccp-pd__demo .ccp-pd__small{font-size:12.5px;color:#9fbbe0;margin:6px 0 0}
.ccp-pd__btn{display:inline-flex;align-items:center;justify-content:center;min-height:50px;padding:12px 26px;border-radius:14px;background:#ffd700;color:#071a33!important;font-weight:850;text-decoration:none!important;box-shadow:0 12px 28px rgba(255,215,0,.28);white-space:nowrap}
.ccp-pd__btn:hover{background:#ffe34d}
@media (max-width:767px){.ccp-pd__grid{grid-template-columns:1fr}.ccp-pd__demo{padding:20px}.ccp-pd__btn{width:100%}}

/* ---- 7. Описание категории (.ccp-cat-desc из sql/05) ---- */
.ccp-cat-desc{color:var(--cc-text,#13294a);line-height:1.7}
.ccp-cat-desc .ccp-cat-desc__lead{font-size:17px;font-weight:600;margin:0 0 12px}
.ccp-cat-desc h3{font-size:16px;font-weight:850;margin:14px 0 8px}
.ccp-cat-desc ul{margin:0 0 12px;padding-left:20px}
.ccp-cat-desc li{margin-bottom:4px}
.ccp-cat-desc .ccp-cat-desc__note{font-size:14px;color:var(--cc-muted,#5b6f8a)}

/* ---- 8. Информационные страницы (политики, условия) ---- */
body.ccp-theme #information-information #content{line-height:1.75}
body.ccp-theme #information-information #content h2{font-weight:850;letter-spacing:-.02em}
body.ccp-theme #information-information #content h3{font-weight:800;margin-top:26px}
' WHERE `store_id`=0 AND `key`='theme_codecart_pro_custom_css_global';
UPDATE `oc_setting` SET `value`='1' WHERE `store_id`=0 AND `key`='theme_codecart_pro_enable_custom_css';
COMMIT;
